// Custom Worker entry: OpenNext's fetch handler plus a cron that retries queued transcriptions.
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as handler } from "./.open-next/worker.js";

const worker = {
  fetch: handler.fetch,

  /** @param {ScheduledController} _event @param {{ CRON_SECRET: string }} env @param {ExecutionContext} ctx */
  async scheduled(_event, env, ctx) {
    const req = new Request("https://internal/api/cron/transcribe", {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};

export default worker;
